 /** Whether one rule applies to a request. See README.md. */
 export function matches(rule: Rule, request: AccessRequest): boolean {
-  throw new Error("not implemented");
+  if (rule.role !== "*" && !request.roles.includes(rule.role)) return false;
+  if (rule.action !== "*" && rule.action !== request.action) return false;
+  return resourceMatches(rule.resource, request.resource);
+}
+
+function resourceMatches(pattern: string, resource: string): boolean {
+  if (pattern === "*" || pattern === resource) return true;
+  if (pattern.endsWith("/*")) return resource.startsWith(pattern.slice(0, -1));
+  return false;
 }

 /** Decide a request against an ordered rule list. */
 export function isAllowed(rules: Rule[], request: AccessRequest): boolean {
-  throw new Error("not implemented");
+  return explain(rules, request).allowed;
 }

 /** Decide a request and say which rule decided it. */
 export function explain(rules: Rule[], request: AccessRequest): Decision {
-  throw new Error("not implemented");
+  const applicable = rules.filter((rule) => matches(rule, request));
+  const deny = applicable.find((rule) => rule.effect === "deny");
+  if (deny) return { allowed: false, rule: deny };
+  const allow = applicable.find((rule) => rule.effect === "allow");
+  return { allowed: allow !== undefined, rule: allow };
 }

